#include <stdio.h>
/*
 * ex06：2-SAT —— 从「每条子句至多两个文字」到线性判定
 * 为什么：3-SAT 是 NP 完全，但 2-SAT 有多项式解法，差别就在「蕴含图 + SCC」。
 *        子句 (a∨b) 等价于两条蕴含 (~a→b) 与 (~b→a)；公式可满足 iff
 *        没有任何变量 xi 使得 xi 与 ~xi 落在同一个强连通分量里。
 * 本例 4 个变量、5 条子句，同时用「暴力枚举」和「蕴含图 SCC」两种方法对照。
 */
#define N 4
#define V (2 * N)
static int g[V][V], gr[V][V];
static int seen[V], order[V], no;
static int comp[V];

static int lit(int var, int neg) { return 2 * var + neg; }
static int neg_of(int l) { return l ^ 1; }

static void dfs1(int u) {
    seen[u] = 1;
    for (int v = 0; v < V; v++) if (g[u][v] && !seen[v]) dfs1(v);
    order[no++] = u;                       /* 后序：完成时间递增 */
}
static void dfs2(int u, int c) {
    comp[u] = c;
    for (int v = 0; v < V; v++) if (gr[u][v] && comp[v] < 0) dfs2(v, c);
}

int main(void) {
    /* 用变量下标+是否取反描述子句，比硬编码节点号更不容易错 */
    int cls[5][2] = {
        {lit(0, 0), lit(1, 0)},   /*  x1 v  x2 */
        {lit(0, 1), lit(2, 0)},   /* ~x1 v  x3 */
        {lit(1, 1), lit(2, 1)},   /* ~x2 v ~x3 */
        {lit(2, 1), lit(3, 0)},   /* ~x3 v  x4 */
        {lit(3, 1), lit(0, 0)}    /* ~x4 v  x1 */
    };
    for (int i = 0; i < 5; i++) {
        int a = cls[i][0], b = cls[i][1];
        g[neg_of(a)][b] = 1;
        g[neg_of(b)][a] = 1;
    }
    for (int u = 0; u < V; u++)
        for (int v = 0; v < V; v++)
            if (g[u][v]) gr[v][u] = 1;
    for (int i = 0; i < V; i++) if (!seen[i]) dfs1(i);
    for (int i = 0; i < V; i++) comp[i] = -1;
    int c = 0;
    for (int i = V - 1; i >= 0; i--) {
        int u = order[i];
        if (comp[u] < 0) dfs2(u, c++);
    }
    printf("literal nodes: 0=x1 1=~x1 2=x2 3=~x2 4=x3 5=~x3 6=x4 7=~x4\n");
    printf("SCC id of each literal:\n  ");
    for (int l = 0; l < V; l++) printf("%d:%d ", l, comp[l]);
    printf("\n\n");
    int ok = 1;
    for (int i = 0; i < N; i++) {
        printf("x%d: SCC(x)=%d, SCC(~x)=%d -> %s\n", i + 1, comp[lit(i, 0)], comp[lit(i, 1)],
               comp[lit(i, 0)] == comp[lit(i, 1)] ? "CONFLICT" : "ok");
        if (comp[lit(i, 0)] == comp[lit(i, 1)]) ok = 0;
    }
    printf("\nSCC verdict: %s\n", ok ? "SATISFIABLE" : "UNSATISFIABLE");
    if (ok) {
        printf("one assignment from SCC order (take the component with larger id):\n  ");
        for (int i = 0; i < N; i++)
            printf("x%d=%d%s", i + 1, comp[lit(i, 0)] > comp[lit(i, 1)], i == N - 1 ? "\n" : " ");
    }
    /* 暴力对拍，防止 SCC 结论自说自话 */
    int models = 0, first[N] = {-1, -1, -1, -1};
    for (int m = 0; m < (1 << N); m++) {
        int sat = 1;
        for (int i = 0; i < 5; i++) {
            int a = (m >> (cls[i][0] / 2)) & 1; if (cls[i][0] & 1) a ^= 1;
            int b = (m >> (cls[i][1] / 2)) & 1; if (cls[i][1] & 1) b ^= 1;
            if (!(a || b)) { sat = 0; break; }
        }
        if (sat) {
            if (models == 0) for (int i = 0; i < N; i++) first[i] = (m >> i) & 1;
            models++;
        }
    }
    printf("\nbrute force over 2^%d = %d assignments: %d model(s)", N, 1 << N, models);
    if (models) {
        printf(", e.g.");
        for (int i = 0; i < N; i++) printf(" x%d=%d", i + 1, first[i]);
        printf("\n");
    } else printf("\n");
    return 0;
}
